using System.Text;

var app = WebApplication.Create(args);
var http = new HttpClient { BaseAddress = new("https://sales.example.com/") };

// Minimal APIs bind ct to the request's token, canceled if the client leaves
app.MapGet("/export", (CancellationToken ct) => BuildCsvAsync(http, ct));
app.Run();

static async Task<string> BuildCsvAsync(HttpClient http, CancellationToken ct)
{
    var csv = new StringBuilder("month,total\n");
    for (var month = 1; month <= 12; month++)
    {
        // ct is accepted but never used: nothing in this loop can stop
        var sales = await http.GetFromJsonAsync<decimal[]>($"sales/{month}");
        csv.AppendLine($"{month},{sales!.Sum()}");
    }
    return csv.ToString();
}

using System.Text;

var app = WebApplication.Create(args);
var http = new HttpClient { BaseAddress = new("https://sales.example.com/") };

// Minimal APIs bind ct to the request's token, canceled if the client leaves
app.MapGet("/export", (CancellationToken ct) => BuildCsvAsync(http, ct));
app.Run();

static async Task<string> BuildCsvAsync(HttpClient http, CancellationToken ct)
{
    var csv = new StringBuilder("month,total\n");
    for (var month = 1; month <= 12; month++)
    {
        ct.ThrowIfCancellationRequested(); // cheap check before each month
        var sales = await http.GetFromJsonAsync<decimal[]>($"sales/{month}", ct);
        csv.AppendLine($"{month},{sales!.Sum()}");
    }
    return csv.ToString();
}

